package com.hospital.appointment.service;

import com.hospital.appointment.client.DoctorServiceClient;
import com.hospital.appointment.client.PatientServiceClient;
import com.hospital.appointment.model.Appointment;
import com.hospital.appointment.repository.AppointmentRepository;
import com.hospital.common.exception.ResourceNotFoundException;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.util.Optional;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class AppointmentServiceTest {

    @Mock
    private AppointmentRepository appointmentRepository;

    @Mock
    private PatientServiceClient patientServiceClient;

    @Mock
    private DoctorServiceClient doctorServiceClient;

    @InjectMocks
    private AppointmentService appointmentService;

    // GreyTest trace: updateAppointmentStatus | không tìm thấy lịch hẹn tại bước tra cứu | BR-009 -> TP-009 -> TC-001
    @Test
    void updateAppointmentStatus_throwsResourceNotFoundExceptionWhenAppointmentDoesNotExist() {
        // Arrange
        Long id = 1001L;
        when(appointmentRepository.findById(id)).thenReturn(Optional.empty());

        // Act
        ResourceNotFoundException exception = assertThrows(
                ResourceNotFoundException.class,
                () -> appointmentService.updateAppointmentStatus(id, Appointment.AppointmentStatus.SCHEDULED));

        // Assert
        assertEquals(String.format("%s not found with %s: '%s'", "Appointment", "id", id), exception.getMessage());
        verify(appointmentRepository).findById(id);
        verify(appointmentRepository, never()).save(org.mockito.ArgumentMatchers.<Appointment>any());
        verify(patientServiceClient, never()).getPatientById(org.mockito.ArgumentMatchers.<Long>any());
        verify(doctorServiceClient, never()).getDoctorById(org.mockito.ArgumentMatchers.<Long>any());
    }
}

