import com.hospital.appointment.model.Appointment;
import com.hospital.appointment.repository.AppointmentRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.LocalTime;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class AppointmentServiceTest {

    @Mock
    private AppointmentRepository appointmentRepository;

    @Mock
    private PatientServiceClient patientServiceClient;

    @Mock
    private DoctorServiceClient doctorServiceClient;

    @InjectMocks
    private AppointmentService appointmentService;

    // GreyTest trace: updateAppointmentStatus | trạng thái CANCELLED đặt cancelledAt và lưu entity | BR-010, BR-012 -> TP-010 -> TC-002
    @Test
    void updateAppointmentStatus_setsCancelledStatusAndCancellationTime() {
        // Arrange
        Long id = 1001L;
        Appointment appointment = new Appointment();
        appointment.setId(id);
        appointment.setPatientId(2001L);
        appointment.setDoctorId(3001L);
        appointment.setAppointmentDate(LocalDate.of(2026, 11, 15));
        appointment.setAppointmentTime(LocalTime.of(10, 30));
        appointment.setStatus(Appointment.AppointmentStatus.SCHEDULED);
        when(appointmentRepository.findById(id)).thenReturn(Optional.of(appointment));
        when(appointmentRepository.save(appointment)).thenAnswer(invocation -> invocation.getArgument(0));
        when(patientServiceClient.getPatientById(2001L))
                .thenReturn(new PatientDto(2001L, "An", "Nguyễn", "an@example.test", "0900000001"));
        when(doctorServiceClient.getDoctorById(3001L))
                .thenReturn(new DoctorDto(3001L, "Bình", "Trần", "Nội khoa", true));

        // Act
        LocalDateTime beforeUpdate = LocalDateTime.now();
        AppointmentResponseDto response = appointmentService.updateAppointmentStatus(id, Appointment.AppointmentStatus.CANCELLED);
        LocalDateTime afterUpdate = LocalDateTime.now();

        // Assert
        ArgumentCaptor<Appointment> savedCaptor = ArgumentCaptor.forClass(Appointment.class);
        verify(appointmentRepository).save(savedCaptor.capture());
        Appointment saved = savedCaptor.getValue();
        assertEquals(Appointment.AppointmentStatus.CANCELLED, saved.getStatus());
        assertNotNull(saved.getCancelledAt());
        assertTrue(!saved.getCancelledAt().isBefore(beforeUpdate) && !saved.getCancelledAt().isAfter(afterUpdate));
        assertEquals(id, saved.getId());
        assertEquals(2001L, saved.getPatientId());
        assertEquals(3001L, saved.getDoctorId());
        assertEquals(LocalDate.of(2026, 11, 15), saved.getAppointmentDate());
        assertEquals(LocalTime.of(10, 30), saved.getAppointmentTime());
        assertEquals(Appointment.AppointmentStatus.CANCELLED, response.getStatus());
        assertEquals("An Nguyễn", response.getPatientName());
        assertEquals("Dr. Bình Trần", response.getDoctorName());
        assertEquals("Nội khoa", response.getDoctorSpecialization());
        verify(appointmentRepository).findById(id);
        verify(patientServiceClient).getPatientById(2001L);
        verify(doctorServiceClient).getDoctorById(3001L);
    }
}

