    // GreyTest trace: updateAppointmentStatus | trạng thái CONFIRMED không đặt timestamp và lưu entity | BR-010, BR-011, BR-012 -> TP-012 -> TC-004
    @Test
    void updateAppointmentStatus_savesStatusAndReturnsEnrichedResponse() {
        // Arrange
        Long id = 1001L;
        Appointment appointment = new Appointment();
        appointment.setId(id);
        appointment.setPatientId(2001L);
        appointment.setDoctorId(3001L);
        appointment.setAppointmentDate(LocalDate.of(2026, 11, 15));
        appointment.setAppointmentTime(LocalTime.of(10, 30));
        appointment.setStatus(Appointment.AppointmentStatus.SCHEDULED);
        when(appointmentRepository.findById(id)).thenReturn(Optional.of(appointment));
        when(appointmentRepository.save(appointment)).thenAnswer(invocation -> invocation.getArgument(0));
        when(patientServiceClient.getPatientById(2001L))
                .thenReturn(new PatientDto(2001L, "An", "Nguyễn", "an@example.test", "0900000001"));
        when(doctorServiceClient.getDoctorById(3001L))
                .thenReturn(new DoctorDto(3001L, "Bình", "Trần", "Nội khoa", true));

