        verify(appointmentRepository).save(savedCaptor.capture());
        Appointment saved = savedCaptor.getValue();
        assertEquals(Appointment.AppointmentStatus.CONFIRMED, saved.getStatus());
        assertEquals(id, saved.getId());
        assertEquals(2001L, saved.getPatientId());
        assertEquals(3001L, saved.getDoctorId());
        assertEquals(LocalDate.of(2026, 11, 15), saved.getAppointmentDate());
        assertEquals(LocalTime.of(10, 30), saved.getAppointmentTime());
        assertEquals(Appointment.AppointmentStatus.CONFIRMED, response.getStatus());
        assertEquals(id, response.getId());
        assertEquals(2001L, response.getPatientId());
        assertEquals(3001L, response.getDoctorId());
        assertEquals(LocalDate.of(2026, 11, 15), response.getAppointmentDate());
        assertEquals(LocalTime.of(10, 30), response.getAppointmentTime());
        assertEquals("An Nguyễn", response.getPatientName());
        assertEquals("Dr. Bình Trần", response.getDoctorName());
        assertEquals("Nội khoa", response.getDoctorSpecialization());
        verify(appointmentRepository).findById(id);
        verify(patientServiceClient).getPatientById(2001L);
        verify(doctorServiceClient).getDoctorById(3001L);
    }
}

