import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.time.LocalDate;
import java.time.LocalTime;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class AppointmentServiceTest {

    @Mock
    private AppointmentRepository appointmentRepository;

    @Mock
    private PatientServiceClient patientServiceClient;

    @Mock
    private DoctorServiceClient doctorServiceClient;

    // GreyTest trace: createAppointment | TERNARY-1::FALSE, STMT-14, STMT-15, STMT-16 | BR-020 -> TP-016 -> TC-013
    @Test
    void createAppointment_NullStatus_UsesScheduledDefault() {
        AppointmentService sut = new AppointmentService(appointmentRepository, patientServiceClient, doctorServiceClient);
        AppointmentRequestDto request = new AppointmentRequestDto(
                101L, 202L, LocalDate.of(2030, 5, 20), LocalTime.of(10, 30), "Khám định kỳ", null, null);
        PatientDto patient = new PatientDto(101L, "An", "Nguyen", "an@example.test", "555-0101");
        DoctorDto doctor = new DoctorDto(202L, "Binh", "Tran", "Cardiology", true);

        when(patientServiceClient.getPatientById(101L)).thenReturn(patient);
        when(doctorServiceClient.getDoctorById(202L)).thenReturn(doctor);
        when(appointmentRepository.findConflictingAppointment(202L, LocalDate.of(2030, 5, 20), LocalTime.of(10, 30)))
                .thenReturn(Optional.empty());
        when(appointmentRepository.save(any(Appointment.class))).thenAnswer(invocation -> {
            Appointment submitted = invocation.getArgument(0);
            submitted.setId(303L);
            return submitted;
        });
        ArgumentCaptor<Appointment> savedCaptor = ArgumentCaptor.forClass(Appointment.class);

        AppointmentResponseDto result = sut.createAppointment(request);

        verify(appointmentRepository).save(savedCaptor.capture());
        Appointment saved = savedCaptor.getValue();
        assertEquals(303L, saved.getId());
        assertEquals(101L, saved.getPatientId());
        assertEquals(202L, saved.getDoctorId());
        assertEquals(LocalDate.of(2030, 5, 20), saved.getAppointmentDate());
        assertEquals(LocalTime.of(10, 30), saved.getAppointmentTime());
        assertEquals("Khám định kỳ", saved.getReason());
        assertNull(saved.getNotes());
        assertEquals(Appointment.AppointmentStatus.SCHEDULED, saved.getStatus());
        assertEquals(303L, result.getId());
        assertEquals(101L, result.getPatientId());
        assertEquals(202L, result.getDoctorId());
        assertEquals(LocalDate.of(2030, 5, 20), result.getAppointmentDate());
        assertEquals(LocalTime.of(10, 30), result.getAppointmentTime());
        assertEquals("Khám định kỳ", result.getReason());
        assertNull(result.getNotes());
        assertEquals(Appointment.AppointmentStatus.SCHEDULED, result.getStatus());
        verify(patientServiceClient, times(1)).getPatientById(101L);
        verify(doctorServiceClient, times(1)).getDoctorById(202L);
    }
}

