import com.hospital.appointment.dto.PatientDto;
import com.hospital.appointment.model.Appointment;
import com.hospital.appointment.repository.AppointmentRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.time.LocalDate;
import java.time.LocalTime;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class AppointmentServiceTest {

    @Mock
    private AppointmentRepository appointmentRepository;

    @Mock
    private PatientServiceClient patientServiceClient;

    @Mock
    private DoctorServiceClient doctorServiceClient;

    @Test
    // GreyTest trace: createAppointment | IF-1-FALSE, STMT-6, TERNARY-1::TRUE, STMT-14, STMT-15, STMT-16 | BR-016, BR-017, BR-018, BR-019, BR-020 -> TP-016 -> TC-012
    void createAppointment_PreservesRequestedStatus() {
        // Arrange
        LocalDate appointmentDate = LocalDate.of(2030, 5, 20);
        LocalTime appointmentTime = LocalTime.of(10, 30);
        AppointmentRequestDto requestDto = new AppointmentRequestDto(
                101L, 202L, appointmentDate, appointmentTime, "Khám định kỳ", null,
                Appointment.AppointmentStatus.NO_SHOW);
        PatientDto patient = new PatientDto(101L, "An", "Nguyen", "an@example.test", "555-0101");
        DoctorDto doctor = new DoctorDto(202L, "Binh", "Tran", "Cardiology", true);
        when(patientServiceClient.getPatientById(101L)).thenReturn(patient);
        when(doctorServiceClient.getDoctorById(202L)).thenReturn(doctor);
        when(appointmentRepository.findConflictingAppointment(202L, appointmentDate, appointmentTime))
                .thenReturn(Optional.empty());
        when(appointmentRepository.save(any(Appointment.class))).thenAnswer(invocation -> {
            Appointment submitted = invocation.getArgument(0);
            submitted.setId(303L);
            return submitted;
        });
        AppointmentService sut = new AppointmentService(
                appointmentRepository, patientServiceClient, doctorServiceClient);

        // Act
        AppointmentResponseDto result = sut.createAppointment(requestDto);

        // Assert
        ArgumentCaptor<Appointment> savedCaptor = ArgumentCaptor.forClass(Appointment.class);
        verify(appointmentRepository).save(savedCaptor.capture());
        Appointment saved = savedCaptor.getValue();
        assertEquals(303L, saved.getId());
        assertEquals(101L, saved.getPatientId());
        assertEquals(202L, saved.getDoctorId());
        assertEquals(appointmentDate, saved.getAppointmentDate());
        assertEquals(appointmentTime, saved.getAppointmentTime());
        assertEquals("Khám định kỳ", saved.getReason());
        assertEquals(null, saved.getNotes());
        assertEquals(Appointment.AppointmentStatus.NO_SHOW, saved.getStatus());

        assertNotNull(result);
        assertEquals(303L, result.getId());
        assertEquals(101L, result.getPatientId());
        assertEquals(202L, result.getDoctorId());
        assertEquals(appointmentDate, result.getAppointmentDate());
        assertEquals(appointmentTime, result.getAppointmentTime());
        assertEquals("Khám định kỳ", result.getReason());
        assertEquals(null, result.getNotes());
        assertEquals(Appointment.AppointmentStatus.NO_SHOW, result.getStatus());
        verify(patientServiceClient).getPatientById(101L);
        verify(doctorServiceClient).getDoctorById(202L);
        verify(appointmentRepository).findConflictingAppointment(202L, appointmentDate, appointmentTime);
    }
}
